from sys import stdin


class TreeNode:
    """Represents a node in a binary search tree."""

    def __init__(self, key):
        self.key = key
        self.parent = None
        self.left = None
        self.right = None


class BinarySearchTree:
    """A binary search tree implementation."""

    def __init__(self):
        self.root = None

    def insert(self, new_node):
        """Inserts a new node into the tree."""
        parent = None
        current = self.root

        while current is not None:
            parent = current
            if new_node.key < current.key:
                current = current.left
            else:
                current = current.right

        new_node.parent = parent
        if parent is None:
            self.root = new_node
        elif new_node.key < parent.key:
            parent.left = new_node
        else:
            parent.right = new_node

    def find(self, key):
        """Finds a key in the tree and returns True if found, False otherwise."""
        current = self.root
        while current is not None:
            if key == current.key:
                return True
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return False

    def _inorder_helper(self, node):
        """Helper method for inorder traversal."""
        if node is not None:
            self._inorder_helper(node.left)
            print("", node.key, end="")
            self._inorder_helper(node.right)

    def print_inorder(self):
        """Prints the tree in inorder traversal."""
        self._inorder_helper(self.root)
        print()

    def _preorder_helper(self, node):
        """Helper method for preorder traversal."""
        if node is not None:
            print("", node.key, end="")
            self._preorder_helper(node.left)
            self._preorder_helper(node.right)

    def print_preorder(self):
        """Prints the tree in preorder traversal."""
        self._preorder_helper(self.root)
        print()


def main():
    """Main function to process input commands."""
    _ = int(stdin.readline())
    tree = BinarySearchTree()

    for line in stdin:
        parts = line.split()
        command = parts[0]

        if command == "insert":
            key = int(parts[1])
            tree.insert(TreeNode(key))
        elif command == "find":
            key = int(parts[1])
            print("yes" if tree.find(key) else "no")
        elif command == "print":
            tree.print_inorder()
            tree.print_preorder()


if __name__ == "__main__":
    main()
